import Debug from './pages/Debug';
import Layby from './pages/Layby';import Profile from './pages/Profile';import SuperAdmin from './pages/SuperAdmin';import {AlertTriangle} from 'lucide-react';
const queryClient=new QueryClient();
function PrivateRoute({children}){const {user,loading,staff,hasActiveSubscription}=useAuth();const navigate=useNavigate();const location=useLocation();useEffect(()=>{if(!loading){if(!user)navigate('/login',{replace:true});else if(staff&&!staff.is_active)navigate('/login',{replace:true});}},[user,loading,staff,navigate]);if(loading)return<div className="min-h-screen flex items-center justify-center">Loading...</div>;if(!user||(staff&&!staff.is_active))return null;if(!hasActiveSubscription&&location.pathname!=='/app/settings'&&staff?.role==='admin'){return(<div className="min-h-screen flex items-center justify-center bg-gray-50 p-4"><div className="bg-white rounded-xl shadow-lg p-8 max-w-md text-center"><AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4"/><h1 className="text-2xl font-bold mb-2">Trial Expired</h1><p className="text-gray-600 mb-6">Your 3-day free trial has ended. Please subscribe to continue.</p><button onClick={()=>navigate('/app/settings')} className="bg-green-600 text-white px-6 py-3 rounded-lg font-medium">Go to Settings to Subscribe</button></div></div>);}return children;}
function PublicRoute({children}){const {user,loading}=useAuth();const navigate=useNavigate();useEffect(()=>{if(!loading&&user)navigate('/app',{replace:true});},[user,loading,navigate]);if(loading)return<div className="min-h-screen flex items-center justify-center">Loading...</div>;return children;}
export default function App(){return(<QueryClientProvider client={queryClient}><AuthProvider><BrowserRouter><Toaster position="top-right"/><AppContent/></BrowserRouter></AuthProvider></QueryClientProvider>);}
